// ===== W1 Code node — HYBRID (round-robin + per-bransch CityIndex) =====

// ---------- Hämta data från noderna ----------
const industriesRows = ($items("Industries", 0) || []).map(i => i.json);
const citiesRows     = ($items("Cities", 0) || []).map(i => i.json);

// Settings som Key/Value-lista -> objekt {Key:Value}
const settingsRows = ($items("Settings", 0) || []).map(i => i.json);
const settings = {};
for (const r of settingsRows) {
  const k = String(r.Key ?? '').trim();
  if (!k) continue;
  settings[k] = r.Value ?? null;
}

// ---------- Parametrar ur Settings (med fallbackar) ----------
const maxCitiesPerRun   = Number(settings.MaxCitiesPerRun    ?? 5);
const currentIndustryRN = Number(settings.CurrentIndustryRow ?? 1); // rad i "Industries"

// ---------- Hjälpfunktioner ----------
function normalizeCountry(v) {
  if (!v) return '';
  const key = String(v).trim().toLowerCase();
  const map = {
    se: 'Sweden', sv: 'Sweden', sverige: 'Sweden',
    no: 'Norway', norge: 'Norway',
    dk: 'Denmark', danmark: 'Denmark',
    fi: 'Finland', suomi: 'Finland'
  };
  return map[key] || (key.length === 2 ? key.toUpperCase()
                                       : key[0].toUpperCase() + key.slice(1));
}
const isTrue = v => (typeof v === 'boolean' ? v : String(v).trim().toLowerCase()) === 'true';
const toInt  = v => {
  // Tål svenskt decimalkomma (t.ex. "0,00") och tomma strängar
  const n = Number(String(v ?? '0').replace(',', '.'));
  return Number.isFinite(n) ? Math.max(0, Math.floor(n)) : 0;
};

// ---------- Filtrera & SORTERA aktiva städer (stabil ordning) ----------
const activeCities = (citiesRows ?? [])
  .filter(c => isTrue(c.Active))
  .sort((a, b) => {
    const ra = toInt(a.row_number), rb = toInt(b.row_number);
    if (ra && rb && ra !== rb) return ra - rb;
    return String(a.City || '').localeCompare(String(b.City || ''));
  });

// ---------- Välj bransch enligt settings.CurrentIndustryRow ----------
const chosenIndustry =
  industriesRows.find(r => Number(r.row_number) === Number(currentIndustryRN)) ||
  industriesRows[0] || {};

if (!chosenIndustry || !chosenIndustry.row_number) {
  // Inga branscher? Avsluta
  return [];
}

// Per-bransch CityIndex — läses från Industries.CityIndex
const perIndustryCityIndex = toInt(chosenIndustry.CityIndex);

// Matcha städer på land om möjligt
const industryCountryRaw = chosenIndustry.Country || '';
const industryCountry    = normalizeCountry(industryCountryRaw);

const poolByCountry = activeCities.filter(c =>
  normalizeCountry(c.Country) === industryCountry
);
const citiesPool = poolByCountry.length ? poolByCountry : activeCities;

// ---------- Bygg batch (wrap-aware läsning) ----------
const total = citiesPool.length;
if (total === 0) { return []; }

const take  = Math.min(maxCitiesPerRun, total);
const start = Math.max(0, perIndustryCityIndex || 0);

// Nästa pekare (SPARA LINJÄRT — ingen wrap här!)
const nextCityIndex = start + take;

// Round-robin: hoppa ALLTID till nästa bransch efter körning
const maxIndustryRow = Math.max(...industriesRows.map(r => Number(r.row_number || 0)));
const nextIndustryRow = (Number(currentIndustryRN) >= maxIndustryRow)
  ? 1
  : Number(currentIndustryRN) + 1;

// Bygg batchen (LÄS med wrap via modulo)
const batch = Array.from({ length: take }, (_, i) => citiesPool[(start + i) % total]);

// ---------- Returnera seeds ----------
const out = batch.map((c, idx) => {
  const cityName    = c.City || c.city || '';
  const cityCountry = `${cityName}, ${industryCountry || (c.Country || '')}`;

  const seed = {
    // Seedkontext
    seed: {
      Industry:    chosenIndustry.Industry,
      Country:     industryCountry,     // normaliserat namn
      City:        cityName,
      CityCountry: cityCountry,         // "City, Country"
      CityIndex:   (start + idx) % total, // visat index för just detta item
      Row:         Number(chosenIndustry.row_number),
    },

    // Lägg både Next* på toppnivå och __next (som WF2 ev. speglar till __control)
    NextIndustryRow: nextIndustryRow,
    NextCityIndex:   nextCityIndex,

    __next: {
      CurrentIndustryRow: nextIndustryRow,
      CurrentCityIndex:   nextCityIndex,
    },
  };

  return { json: seed };
});

// Lägg __control på FÖRSTA itemet (samma info som __next)
if (out.length) {
  out[0].json.__control = { ...out[0].json.__next };
}

return out;

// Extract __control — PRIORITERA Build W2 payload
// Producerar exakt två items till Settings: {Key,Value}.

function toInt(v){
  const n = Number(String(v ?? '').replace(',', '.'));
  return Number.isFinite(n) ? Math.trunc(n) : null;
}

// 1) Försök hämta direkt från "Build W2 payload" (säker, deterministisk källa)
let src = null;
try {
  const bwp = $items('Build W2 payload', 0, 0) || [];
  if (Array.isArray(bwp) && bwp[0] && bwp[0].json) {
    src = bwp[0].json;
  }
} catch { /* ignore */ }

// 2) Fallback: sök i inkommande items (från Execute Workflow / andra grenar)
if (!src) {
  const incoming = $input.all().map(it => it.json || {});
  src = incoming.find(j =>
    j && (
      j.NextIndustryRow != null || j.NextCityIndex != null ||
      (j.__next && (j.__next.CurrentIndustryRow != null || j.__next.CurrentCityIndex != null))
    )
  ) || null;
}

// 3) Sista fallback: om Route "settings" råkar vara det enda som finns, bygg från Key/Value
if (!src) {
  const routeSettings = $items('Route control items', 0, 0) || [];
  const rowItem = routeSettings.find(it => it.json?.Key === 'CurrentIndustryRow');
  const idxItem = routeSettings.find(it => it.json?.Key === 'CurrentCityIndex');
  if (rowItem || idxItem) {
    return [
      { json: { Key: 'CurrentIndustryRow', Value: toInt(rowItem?.json?.Value) } },
      { json: { Key: 'CurrentCityIndex',   Value: toInt(idxItem?.json?.Value) } },
    ];
  }
}

// Bygg de nya pekarna
const nextRow = toInt(src?.NextIndustryRow ?? src?.__next?.CurrentIndustryRow);
const nextIdx = toInt(src?.NextCityIndex   ?? src?.__next?.CurrentCityIndex);

return [
  { json: { Key: 'CurrentIndustryRow', Value: nextRow } },
  { json: { Key: 'CurrentCityIndex',   Value: nextIdx } },
];

// Filtrera bort tomma/ogiltiga branschrader
// Krav: Active==TRUE och Industry har text
function t(v){ return (v ?? '').toString().trim(); }
const out=[];
for (const it of items){
  const r = it.json || {};
  const Industry = t(r.Industry);
  const Active   = String(r.Active || '').toLowerCase() === 'true';
  // country kan vara tom – fyller vi senare i seed om staden har land
  if (!Active || !Industry) continue;   // släng tomma/inaktiva rader
  out.push({ json: { ...r, Industry }});
}
return out;

// Filtrera bort tomma stadsrader
// Krav: City finns. Country valfritt (men bra om det finns)
function t(v){ return (v ?? '').toString().trim(); }
const out=[];
for (const it of items){
  const r = it.json || {};
  const City = t(r.City);
  const Country = t(r.Country); // får vara '' – vi hanterar fallback i seed
  if (!City) continue;          // släng tomma rader
  out.push({ json: { ...r, City, Country }});
}
return out;

// Build control items — lägg "next"-pekare både för Settings och Industries
const j = $json || {};

const toInt = v => {
  const n = Number(String(v ?? '').replace(',', '.'));
  return Number.isFinite(n) ? Math.trunc(n) : 0;
};

const nextRow = toInt(
  j.NextIndustryRow ??
  j.__next?.CurrentIndustryRow ??
  j.__control?.CurrentIndustryRow
);

const nextIdx = toInt(
  j.NextCityIndex ??
  j.__next?.CurrentCityIndex ??
  j.__control?.CurrentCityIndex
);

// För industrinamnet — ta från seed/nuvarande payload
const name = String(j.seed?.Industry ?? j.Industry ?? '').trim();

// Vi returnerar TRE control-items:
// 1–2) Settings-pekare (Key/Value)  3) Industries med CityIndex = NEXT
const out = [
  { json: { __target: 'settings',   Key: 'CurrentIndustryRow', Value: nextRow } },
  { json: { __target: 'settings',   Key: 'CurrentCityIndex',   Value: nextIdx } },
];

if (name) {
  out.push({ json: { __target: 'industries', Industry: name, CityIndex: nextIdx } });
}

return out;

// Keep industries control — normalisera namn + bygg stabil matchnyckel
// Output: { Industry, IndustryKey, CityIndex }

const j = $json || {};

// Endast items som är avsedda för Industries-tabellen
if (j.__target !== 'industries') {
  return [];
}

// Hjälpfunktioner
function toInt(v) {
  const n = Number(String(v ?? '0').replace(',', '.'));
  return Number.isFinite(n) ? Math.trunc(n) : 0;
}

function cleanName(s) {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' '); // enkelspacia
}

// Hämta branschnamn (krävs)
const nameRaw = String(j.Industry ?? '').trim();
if (!nameRaw) return [];

// Hämta CityIndex (acceptera flera fält-namn för robusthet)
const idx =
  toInt(j.NextCityIndex) ||   // primär: nästa index beräknat tidigare i W1
  toInt(j.CityIndex)     ||   // fallback om NextCityIndex saknas
  0;

// Bygg normaliserad nyckel
const nameKey = cleanName(nameRaw);

// Returnera objektet som upserten ska använda
return {
  json: {
    Industry: nameRaw,     // “snyggt” visningsnamn (behålls i arket om du mappar det)
    IndustryKey: nameKey,  // STABIL matchnyckel (matcha på denna i upsert-noden)
    CityIndex: idx
  }
};

// Build W2 payload — räkna fram NextCityIndex och bädda in i seeds till W2

// ===== Hjälpare =====
const toInt = v => {
  const n = Number(String(v ?? '0').replace(',', '.'));
  return Number.isFinite(n) ? Math.trunc(n) : 0;
};

// ===== 1) Läs styrvärden (nuvarande pekare) ur inkommande items =====
// I din setup brukar föregående noder föra med __control eller __next
const incoming = $input.all().map(it => it.json || {});
const ctrl  = incoming.find(j => j.__control) || {};
const next  = incoming.find(j => j.__next)    || {};

const CURRENT_ROW   = toInt(ctrl.CurrentIndustryRow ?? next.CurrentIndustryRow ?? $json.CurrentIndustryRow);
const CURRENT_INDEX = toInt(ctrl.CurrentCityIndex   ?? next.CurrentCityIndex   ?? $json.CurrentCityIndex);

// ===== 2) Hämta seeds (städer) för DENNA körning =====
// Dina seeds ligger redan i input (från Loop Over Items/Build batch).
const cities = incoming
  .filter(it => it.seed)
  .map(it => {
    const s = it.seed;
    return {
      Industry:     String(s.Industry || '').trim(),
      Country:      String(s.Country  || '').trim(),
      City:         String(s.City     || '').trim(),
      CityCountry:  String(s.CityCountry || '').trim(),
      Row:          toInt(s.Row),
    };
  });

// Sätt en rimlig fallback om något saknas
const MAX_PER_RUN = 5;

// ===== 3) Beräkna nästa CityIndex =====
const usedCount = cities.length > 0 ? cities.length : MAX_PER_RUN;

// Om du har en nod i W1 som innehåller HELA stadlistan för branschen, ange dess namn här
function getLenOf(nodeName){
  try {
    const arr = $items(nodeName);
    return Array.isArray(arr) ? arr.length : 0;
  } catch { return 0; }
}

// Prova några vanliga kandidater, annars fallback = usedCount
const citiesTotal =
  getLenOf('Cities (selected)') ||
  getLenOf('Cities filtered')   ||
  getLenOf('Cities')            ||
  getLenOf('Read Cities')       ||
  usedCount;

// Wrap-baserad uppdatering (0..citiesTotal-1)
const nextCityIndex = (CURRENT_INDEX + usedCount) % Math.max(1, citiesTotal);

// ===== 4) (Valfritt) Nästa branschrad =====
// Enkel ökning med 1 (wrap logik kan ligga i annan nod senare)
const nextIndustryRow = CURRENT_ROW + 1;

// ===== 5) Returnera payload till W2 =====
return cities.map(c => ({
  json: {
    ...c,
    CityIndex:       CURRENT_INDEX,  // startindex som denna körning använde
    NextCityIndex:   nextCityIndex,  // pekare som W1 ska skriva till Industries
    NextIndustryRow: nextIndustryRow // pekare som W1 ska skriva till Settings
  }
}));

const req = ['Industry','Country','City','CityCountry'];
const out = [];

for (const it of $input.all()) {
  const j = it.json || {};
  const miss = req.filter(k => !String(j[k] ?? '').trim());
  if (miss.length) { 
    console.warn('Skip item, missing:', miss, j); 
    continue; 
  }
  out.push({ json: j });
}

return out; // flera items vidare till Execute Workflow
